"""Recipe search: filter a recipe list by tags, cook time and pantry."""

from dataclasses import dataclass, field

STEP_MINUTES = 5


@dataclass
class FilterState:
    tags: set = field(default_factory=set)
    max_minutes: int | None = None
    pantry: set = field(default_factory=set)
    pantry_only: bool = False


def _rounded(minutes: int) -> int:
    """Round up to the slider's steps."""
    return -(-minutes // STEP_MINUTES) * STEP_MINUTES


def _matches(
    recipe: dict, state: FilterState, cap: int | None
) -> bool:
    """True when the recipe passes every active filter."""
    if state.tags and not state.tags <= set(recipe["tags"]):
        return False
    if cap is not None and recipe["minutes"] > cap:
        return False
    if state.pantry_only and not set(recipe["needs"]) <= state.pantry:
        return False
    return True


def search(recipes: list[dict], state: FilterState) -> list[dict]:
    cap = None if state.max_minutes is None else _rounded(state.max_minutes)
    return [recipe for recipe in recipes if _matches(recipe, state, cap)]

